draw:
var hc = 1240;
var Eph = hc / p.lam;
var K = Eph - p.phi;
var Vstop = K > 0 ? K : 0;
var flows = (K > 0) && (p.V < K);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var xc = W * 0.22, xa = W * 0.78;
var yTop = H * 0.18, yBot = H * 0.74;
var ymid = (yTop + yBot) / 2;
var gap = xa - xc;

// plates
ctx.strokeStyle = C.ink;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(xc, yTop); ctx.lineTo(xc, yBot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xa, yTop); ctx.lineTo(xa, yBot); ctx.stroke();
ctx.lineWidth = 1.5;

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("cathode", xc, yBot + 16);
ctx.fillText("anode", xa, yBot + 16);
ctx.fillText("retarding voltage " + p.V.toFixed(2) + " V", (xc + xa) / 2, H - 8);

// incoming light: three photon markers sliding in from the left
var i, s, px, py;
ctx.strokeStyle = C.accent;
for (i = 0; i < 3; i++) {
  s = ((t * 0.7 + i * 0.333) % 1);
  px = xc * s;
  py = yTop + (yBot - yTop) * (0.25 + 0.25 * i);
  ctx.beginPath();
  ctx.moveTo(px - 14, py);
  ctx.lineTo(px, py);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(px, py); ctx.lineTo(px - 5, py - 3.5); ctx.lineTo(px - 5, py + 3.5);
  ctx.closePath();
  ctx.fillStyle = C.accent;
  ctx.fill();
}
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("light, " + p.lam.toFixed(0) + " nm", 4, yTop - 6);

// electrons
var n = 4, reach, ex;
ctx.textAlign = "center";
for (i = 0; i < n; i++) {
  s = ((t * 0.55 + i / n) % 1);
  if (K <= 0) { continue; }
  if (flows) {
    ex = xc + gap * s;
  } else {
    reach = p.V > 0 ? Math.min(K / p.V, 1) : 1;
    ex = xc + gap * reach * (1 - (2 * s - 1) * (2 * s - 1));
  }
  py = ymid + (i - 1.5) * (yBot - yTop) * 0.16;
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(ex, py, 4, 0, Math.PI * 2); ctx.fill();
}

if (K <= 0) {
  ctx.fillStyle = C.figure;
  ctx.fillText("no emission: photon is below the work function", (xc + xa) / 2, ymid);
} else if (!flows) {
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([3, 4]);
  var turn = xc + gap * Math.min(K / Math.max(p.V, 1e-9), 1);
  ctx.beginPath(); ctx.moveTo(turn, yTop); ctx.lineTo(turn, yBot); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.figure;
  ctx.fillText("turned back", turn, yTop - 6);
}

// ammeter
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(xc, yBot); ctx.lineTo(xc, H * 0.88);
ctx.lineTo(xa, H * 0.88); ctx.lineTo(xa, yBot);
ctx.stroke();
ctx.fillStyle = flows ? C.accent : C.faint;
ctx.beginPath(); ctx.arc((xc + xa) / 2, H * 0.88, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("A", (xc + xa) / 2, H * 0.88 + 4);

out.note = "photon " + Eph.toFixed(2) + " eV, work function " + p.phi.toFixed(2)
  + " eV, Kmax " + (K > 0 ? K.toFixed(2) : "0.00") + " eV, stopping potential "
  + Vstop.toFixed(2) + " V, current " + (flows ? "flowing" : "zero");
